<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class ControlMapService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    private function point(array $r):?array {if(!isset($r['latitude'],$r['longitude'])||!is_numeric($r['latitude'])||!is_numeric($r['longitude'])||!is_finite((float)$r['latitude'])||!is_finite((float)$r['longitude'])||abs((float)$r['latitude'])>90||abs((float)$r['longitude'])>180)return null;return ['latitude'=>(float)$r['latitude'],'longitude'=>(float)$r['longitude']];}
    public function snapshot(array $input):array {
        $this->fields($input,['site_id']);$site=$this->access->requireSite($input['site_id']??null);$now=gmdate('Y-m-d H:i:s');$params=['company'=>$this->company(),'site'=>$site['site_id']];$shifts=$this->db->fetchAll("SELECT * FROM shift_assignments WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND assignment_status IN ('ASSIGNED','CONFIRMED','IN_PROGRESS') AND shift_start_at<=:now AND shift_end_at>=:end ORDER BY employee_id,shift_assignment_id DESC LIMIT 501",$params+['now'=>$now,'end'=>$now]);if(count($shifts)>500)throw HttpException::unprocessable('Map duty exceeds 500 shifts.');$guards=[];$seen=[];
        foreach($shifts as$s){$employee=(string)$s['employee_id'];if(isset($seen[$employee]))continue;$seen[$employee]=true;$location=$this->db->fetch('SELECT * FROM gps_locations WHERE company_id=:company AND employee_id=:employee AND captured_at>=:start AND captured_at<=:end ORDER BY captured_at DESC LIMIT 1',['company'=>$this->company(),'employee'=>$employee,'start'=>$s['shift_start_at'],'end'=>$s['shift_end_at']]);$point=$location?$this->point($location):null;$age=$location?time()-strtotime($location['captured_at'].' UTC'):null;$state=$point===null?'UNKNOWN':($age< -120?'INVALID_TIME':($age>300?'STALE':'RECENT'));$guards[]=['employee_id'=>$employee,'shift_id'=>$s['shift_assignment_id'],'position'=>$state==='INVALID_TIME'?null:$point,'captured_at'=>$location['captured_at']??null,'age_seconds'=>$age===null?null:max(0,$age),'state'=>$state,'accuracy_metres'=>isset($location['accuracy'])?(float)$location['accuracy']:null,'mock_location'=>!empty($location['mock_location'])];}
        $incidents=$this->db->fetchAll("SELECT incident_id,incident_number,severity,status,occurred_at FROM incidents WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND status IN ('OPEN','INVESTIGATING') ORDER BY incident_id DESC LIMIT 100",$params);
        $patrols=$this->db->fetchAll("SELECT p.patrol_session_id,p.patrol_route_id,p.status,p.started_at FROM patrol_sessions p JOIN patrol_routes r ON r.company_id=p.company_id AND r.patrol_route_id=p.patrol_route_id WHERE p.company_id=:company AND r.site_id=:site AND p.deleted_at IS NULL AND p.started_at>=:start ORDER BY p.patrol_session_id DESC LIMIT 100",$params+['start'=>gmdate('Y-m-d').' 00:00:00']);
        foreach($patrols as&$p){$p['checkpoint_total']=(int)$this->db->fetch('SELECT COUNT(*) AS n FROM patrol_checkpoints WHERE company_id=:company AND patrol_route_id=:route AND deleted_at IS NULL AND status=:status',['company'=>$this->company(),'route'=>$p['patrol_route_id'],'status'=>'ACTIVE'])['n'];$p['checkpoint_visits']=(int)$this->db->fetch('SELECT COUNT(DISTINCT patrol_checkpoint_id) AS n FROM patrol_checkpoint_events WHERE company_id=:company AND patrol_session_id=:session AND event_type=:visited',['company'=>$this->company(),'session'=>$p['patrol_session_id'],'visited'=>'VISITED'])['n'];}unset($p);
        $this->audit->record('control_map','viewed',(string)$site['site_id']);return ['site'=>['site_id'=>$site['site_id'],'site_name'=>$site['site_name'],'position'=>$this->point($site)],'guards'=>$guards,'incidents'=>$incidents,'patrols'=>$patrols,'generated_at'=>$now,'stale_after_seconds'=>300,'note'=>'Recorded positions during current assigned duty only. Older than five minutes is stale; missing data is unknown. Incident markers use the site position, not an independently captured incident location. Patrol progress reflects server-received records and may lag offline capture.'];
    }
}
